internal sealed class AttenuatorDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/QuantumChannels/FockAttenuator/Attenuator.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/QuantumStates/vanherstraeten2024nongaussian");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The full bosonic attenuator and the coherent-state output-entropy question.",
        H("Attenuator"),
        Blocks(
            Paragraph(Text("Corrected balanced Fock-two argument. The new analytic arguments in this narrative and the companion Entropy narrative are independently source-assessed mathematics pending formalization; the cited existing Lean declarations retain their own frozen scope and do not prove the new classification or countable entropy bridges. The parent problem is S(Phi(rho)) >= (3/2) log 2 for every density on completed Fock space, where Phi is the actual eta=1/2 channel with environment |2><2|. It remains open. More generally, Conjecture 1 of Van Herstraeten, Guha and Cerf, arXiv:2312.15623v2, Section IV, asks for coherent-state minimum output entropy for every eta and every number-state environment n, with possible additional minimizers. The rank-three result below is a restriction on the competing inputs, and the conditional determinant argument in Entropy leaves a universal premise unproved. Neither settles Conjecture 1 or the all-input partial-progress question in issue #17675. No finite input support, finite energy or finite entropy is assumed.")),
            Paragraph(Text("Physical coefficient correspondence. Write a completed-Fock vector as a=(a_k) in l2 and its Bargmann entire function as f(z)=sum_{k>=0} a_k z^k/sqrt(k!). The beamUnitary_fock convention sends f tensor |2> at eta=1/2 to F(z,w)=f((z+w)/sqrt(2)) (w-z)^2/(2 sqrt(2)). In normalized occupation coordinates, put N=i+j. Its coefficient matrix C_a has C_ij=0 for N<2 and C_ij=a_{N-2} sqrt(binomial(N,i)/2^N) ((i-j)^2-N)/sqrt(2N(N-1)) for N>=2. Indeed, expanding (w-z)^2(z+w)^{N-2}, the coefficient at z^i w^{N-i} is binomial(N-2,i)-2binomial(N-2,i-1)+binomial(N-2,i-2); division by binomial(N,i) gives ((N-2i)^2-N)/(N(N-1)), including the endpoint convention that out-of-range binomial coefficients vanish. Restoring occupation factorials gives the displayed C_ij. If I has binomial(N,1/2) law, E[((2I-N)^2-N)^2]=2N(N-1), so summing each anti-diagonal gives ||C_a||_HS^2=sum_k |a_k|^2. This is the exact completed-space isometry, not an assigned spectrum. With i retained, the pure output is C_a C_a^*, and its rank is the Schmidt or separation rank of F. The full square-root channel and its pure-input realization are the existing attenuatorOperator and pureAttenuatorOperator; their identification is also used inside PhaseCovariantAttenuatorCoherentRefutation.result.")),
            Paragraph(Text("Completed pure and density identification for the purity argument. At balance, the same orthogonal substitution turns V f into f(x)e2(y), so its isometry holds on the entire completed Fock space. A source DensityOperator is an arbitrary positive trace-class density: the sum of its full occupation diagonal is one, equivalently the positive square root has Hilbert-Schmidt norm one. The columns sqrt(rho)e_m satisfy sum_m |sqrt(rho)e_m><sqrt(rho)e_m|=rho in trace norm. Thus the source outputVector and attenuatorOperator are exactly the reduced beam-splitter map on rho tensor |2><2|, including off-diagonal and infinite-rank rho; pureOutputVector and pureAttenuatorOperator give its actual pure specialization C_a C_a^*. The completed-vector beam_displacement and partialTrace_pairDisplacement declarations, rather than only coherent_output_covariance, provide covariance for arbitrary inputs without a photon moment. The companion Entropy narrative uses this full identification for the two-copy compression, coherent equality and quantitative pure/density stability; these analytic consequences remain pending formalization.")),
            Paragraph(Text("Finite output rank forces an exponential polynomial. Rescaling the two complex variables preserves separation rank and replaces F by a nonzero scalar multiple of K(z,w)=(z-w)^2 f(z+w). For a finite-rank Hilbert-Schmidt coefficient operator, a singular-vector decomposition gives finitely many products of Bargmann entire functions; conversely a finite separation into entire factors bounds the analytic coefficient rank, which equals the operator rank when finite. Thus finite operator rank and finite analytic separation rank agree. Applying (partial_z-partial_w)^2 to K gives 8f(z+w). Differentiating a finite separated sum leaves a finite separated sum, so the ordinary Hankel kernel f(z+w) has finite rank. This operation takes place among entire functions and makes no assertion that differentiation is bounded on the Fock Hilbert space.")),
            Paragraph(Text("Let W be the span of all translates f(.+w), w in C. The finite-rank Hankel kernel puts W in a finite-dimensional space. Translation preserves W, and W is closed in the compact-open topology because it is finite dimensional. Difference quotients converge uniformly on compact sets to the derivative, so differentiation preserves W. If p is the characteristic polynomial of the linear map partial_z on W, Cayley-Hamilton gives p(partial_z)f=0. Factoring p over C and solving the constant-coefficient ODE gives f(z)=sum_alpha exp(alpha z) P_alpha(z), a finite sum with distinct alpha and nonzero polynomials P_alpha. Conversely each such function belongs to Bargmann Fock space, since polynomial growth times an exponential is square-integrable against the Gaussian, and its kernel K has finite separation rank by polynomial expansion. This proves the required entire-function statement directly. Engert, Finite dimensional translation invariant subspaces, Pacific J. Math. 32 (1970), 333-343, Theorem 1, printed p.340, DOI 10.2140/pjm.1970.32.333, treats a sigma-compact locally compact abelian group and measurable complex functions modulo almost-everywhere equality. Its group exponential-polynomial conclusion needs pointwise recovery and holomorphic specialization here. The direct ODE proof supplies precisely those analytic conditions. Primary text: https://msp.org/pjm/1970/32-2/pjm-v32-n2-p05-s.pdf. Engert also credits earlier continuous real-line work, including Anselone-Korevaar and Loewner; no priority inference is made.")),
            Paragraph(Text("Ranks add across distinct exponentials. For each alpha let m_alpha=deg P_alpha and use exp(alpha z) z^j, 0<=j<=m_alpha+2, as a basis in the first variable and the corresponding basis in the second. These exponential-polynomial spaces for different alpha are linearly independent: applying products of sufficiently high powers of partial_z-alpha isolates each summand, or equivalently uses the distinct generalized eigenspaces of differentiation. Since exp(alpha(z+w))=exp(alpha z)exp(alpha w), the finite coefficient matrix for K is block diagonal in these independent bases. Its rank is exactly the sum of the ranks of the nonzero polynomial blocks (z-w)^2 P_alpha(z+w). Lower coefficients and different exponentials therefore cannot cancel ranks between blocks.")),
            Paragraph(Text("All degrees in one polynomial block. Let P have nonzero leading coefficient and degree m, and set N=m+2. Apart from that leading coefficient, the coefficient on its top anti-diagonal z^i w^{N-i} is binomial(N,i) ((N-2i)^2-N)/(N(N-1)). At most two of the N+1 positions vanish, because the vanishing condition is quadratic in i. Choose all surviving row indices increasingly and their complementary column indices decreasingly. In the resulting square submatrix the diagonal is nonzero, and entries below it have total degree greater than N and vanish. The triangular minor is nonzero regardless of the lower coefficients of P. If m>=3 this gives rank at least N-1=m+1>=4. No exact rank formula for higher degrees is needed. For m=0 the three top anti-diagonal coefficients are nonzero and there are only three rows, so the rank is exactly three. For m=1 all four top anti-diagonal coefficients are nonzero and there are only four rows, so the rank is exactly four.")),
            Paragraph(Text("The quadratic block, including complex coefficients. Write P(z)=a0+a1 z+a2 z^2/sqrt(2), a2!=0. In the physical occupation basis the endpoint rows and columns give two nonzero pivots. Eliminating them leaves the 2 by 2 block [[-a0/sqrt(2),-a1/sqrt(8)],[-a1/sqrt(8),-a2/2]], hence rank C=2+rank of that block. It is never zero, and its determinant is a0 a2/(2 sqrt(2))-a1^2/8. Consequently it has rank one exactly when a1^2=2 sqrt(2) a0 a2, and otherwise rank two. This is precisely the zero-discriminant condition for P. Thus a quadratic double root gives rank three; a quadratic with distinct roots gives rank four. The argument is over C and does not assume real input coefficients.")),
            Paragraph(Text("Exhaustive pure-input classification. Every nonzero exponential block has rank at least three. Rank three therefore requires one exponential and a polynomial that is either constant or quadratic with a double root. For any nonzero completed-Fock pure input, rank Phi(|f><f|)=3 if and only if, up to a nonzero normalization factor, f(z)=exp(alpha z) or f(z)=exp(alpha z)(z-beta)^2. There is no nonzero pure input with output rank below three. A function outside the finite exponential-polynomial class has infinite output rank. These conclusions quantify over arbitrary completed vectors; the polynomial calculations are the consequence of finite output rank, not an imposed finite occupation cutoff.")),
            Paragraph(Text("Covariance and the shifted root. In the source Weyl convention D(gamma)f(z)=exp(-|gamma|^2/2+gamma z) f(z-conj(gamma)). Thus D(-alpha)[exp(alpha z)(z-beta)^2] is a nonzero constant times (z-(beta-conj(alpha)))^2. The invariant radial parameter after displacement is r=|beta-conj(alpha)|, not |beta|. The beam_displacement and partialTrace_pairDisplacement identities provide the completed-vector displacement transport; coherent_output_covariance is the coherent special case. For the number-state environment phase rotation is also covariant: replacing a_k by exp(ik theta)a_k changes C to exp(-2i theta) D_theta C D_theta^T, where D_theta is diagonal with entries exp(ij theta). Hence C C^* changes by unitary conjugation. This direct coefficient calculation supplies arbitrary-input phase covariance; it is not inferred from coherent_output_covariance. A phase can therefore put every noncoherent rank-three case in the form f_r(z)=(z+r)^2/sqrt(Z), r>=0, x=r^2, Z=x^2+4x+2, with Fock coefficients (x,2r,sqrt(2))/sqrt(Z). The source's unitary entropy transport is already used inside PhaseCovariantAttenuatorCoherentRefutation.result.")),
            Paragraph(Text("Compression of the actual occupation matrix. Before division by sqrt(Z), row 0 couples to rows 2,3,4 with entries x/2, sqrt(6)r/2, sqrt(3)/2, respectively. The block on rows and columns {1,2} is -(1/sqrt(2)) [[x,r],[r,1]]. Rotate its rank-one direction onto (r,1)/sqrt(x+1); its nonzero entry is -s, s=(x+1)/sqrt(2). Row 0 then couples to this direction with u=x/(2sqrt(x+1)). Its remaining coupling vector has squared norm v^2=x^3/(4(x+1))+3x/2+3/4=P/(4(x+1)), P=x^3+6x^2+9x+3; rotate that vector onto one further axis. The only nonzero compression is B/sqrt(Z), with B=[[0,u,v],[u,-s,0],[v,0,0]]. These are orthogonal changes of basis in the physical coefficient matrix. In particular det B=s v^2 is nonzero. Its three real nonzero eigenvalues mu_i are the roots of mu^3+s mu^2-T mu-s v^2=0, T=u^2+v^2=(x^2+6x+3)/4. The three nonzero physical output eigenvalues are mu_i^2/Z. The Entropy narrative derives the exact symmetric coefficients, strict entropy bound, mixed-support extension and equality cases from this compression.")),
            Paragraph(Text("Source scope and literature correspondence. The model correspondence uses BeamSplitter.beamUnitary_fock, Attenuator's square-root ensemble and pureAttenuatorOperator, and DisplacementCovariance's completed-vector identities at source revision 1ecf52f8c59f714ae936b8cea08c578355c80946 (Lean 4.35.0, Mathlib 56a005855ea17e0b0958f73ec801ae140b0a1679). Van Herstraeten, Guha and Cerf, https://arxiv.org/html/2312.15623v2, equation (44), gives displacement covariance for arbitrary environments; Lemma 1 requires rotation/reflection symmetry, satisfied by |2><2|, and equation (45) defines the physical Fock attenuator. Its Conjecture 1 does not supply the classification above. Lupu-Gladstein, Hertz, Heshami and Goldberg, Entanglement, loss, and quantumness: When balanced beam splitters are best, https://arxiv.org/html/2411.03423v1, Theorems 7,9,11, addresses respectively vacuum-loss purity for pure inputs, finite-support G-concurrence with an infinite-product warning, and mixed-input convex-roof entanglement with vacuum environment. Mode exchange and that mixed extension do not replace vacuum by fixed |2><2| with arbitrary competing input. Existing frozen vacuum-loss, Wigner-majorization and mixed-environment Conjecture 2 results likewise do not close the present Fock-two problem. These are checks of exact hypotheses in the cited literature and a bounded source overlap check, not an exhaustive absence or priority claim.")),
            Paragraph(Text("Three-copy realization on the full completed domain. Let H be Bargmann-Fock space with orthonormal basis e_k(z)=z^k/sqrt(k!), and write V f(z,w)=f((z+w)/sqrt(2))(w-z)^2/(2sqrt(2)). The orthogonal substitution x=(z+w)/sqrt(2), y=(w-z)/sqrt(2) preserves the Gaussian norm, and y^2/sqrt(2) has norm one. Hence V is an isometry for every a in complex l2, with no mean-photon-number assumption. Define the orthogonal antisymmetrizer P_alt=(1/6)sum_{pi in S3} sign(pi)U_pi on three retained outputs and Q=(V tensor3)^*(P_alt,A tensor I_B)(V tensor3). Then 0<=Q<=I and e3(C_a C_a^*)=<a tensor3,Q(a tensor3)>. The factor 1/6 belongs to the antisymmetrizer; there is no extra factorial in this expectation or in the increasing-triple exterior basis. The physical question is nonnegativity of Q-I/32 on actual tensor cubes a tensor3. The stronger assertion of positivity on every symmetric three-copy vector fails, as shown in Entropy.")),
            Paragraph(Text("Center and relative coordinates, without a center cutoff. For the three input variables put t=(x1+x2+x3)/sqrt(3), u=(x1-x2)/sqrt(2), v=(x1+x2-2x3)/sqrt(6), c=t/sqrt(3), and r_i=x_i-c. Then sum_i r_i=0, h2=sum_i r_i^2=u^2+v^2, and h3=r1 r2 r3=(3u^2v-v^3)/(3sqrt(6)). Apply the same orthogonal change to the environment and both output triples. The three identical splitters separate into center and relative splitters. A retained-output permutation acts identically on its center, so its conjugation cancels the center splitter. Taking the environment expectation yields Q=I_center tensor q. The transformed environment |2,2,2> still has six photons; writing it as sum_{d=0}^6 |6-d>_center tensor chi_d and tracing the center gives a positive trace-one relative density block diagonal in d. Relative photon conservation gives q=direct_sum_{M>=0}q_M. All steps use bounded unitaries and projections on completed spaces. No differentiation operator on H is used here.")),
            Paragraph(Text("The invariant relative sectors and their physical components. Simultaneous copy permutations intertwine the splitters, fix the environment and preserve P_alt; consequently q_M preserves the S3-invariant relative subspace. The fundamental theorem of symmetric polynomials with sum r_i=0 identifies its polynomial algebra as C[h2,h3], since h2=-2e2(r) and h3=e3(r). An exact basis at degree M is {h2^p h3^j:2p+3j=M}. The invariant space is one-dimensional for M=0,2,3,4,5, absent for M=1, and of dimension at most 11 for M<64. These dimensions concern the invariant subspaces, not the full relative degree-M spaces. Define F_a(t,u,v)=product_{i=1}^3 f(c+r_i) and let F_{a,M} be its orthogonal relative-degree-M projection. It is the transformed physical tensor cube, so every component is invariant and sum_M ||F_{a,M}||^2=||a||^6. Every center coefficient is retained as a vector of the entire completed center space.")),
            Paragraph(Text("Exact same-function differential polynomials. Every prime in this paragraph denotes the ordinary complex derivative in the Bargmann argument c, and every occurrence of f or a derivative is evaluated at c. Define P3=(f^2 f'''-3f f' f''+2(f')^3)/2, P4=(f^2 f''''-4f f' f'''+3f(f'')^2)/48, and P5=(f^2 f'''''-5f f' f''''+2f f'' f'''+8(f')^2 f'''-6f'(f'')^2)/48. The full projected vectors are F_{a,3}=P3(t/sqrt(3))h3, F_{a,4}=P4(t/sqrt(3))h2^2, and F_{a,5}=P5(t/sqrt(3))h2h3. They obey the entire identity f(c)P5(c)=f(c)P4'(c)-3f'(c)P4(c). If the center coefficient is differentiated in t instead, P4'(c) is sqrt(3) times d[P4(t/sqrt(3))]/dt. Thus changing derivative variables changes that coefficient.")),
            Paragraph(Text("Derivation and behavior at zeros. The power sums of r_i are p2=h2, p3=3h3, p4=h2^2/2 and p5=5h2h3/2. On any disk where f is nonzero, choose a local g=log f and expand exp(sum_i g(c+r_i)). Its relative degrees three, four and five are f^3 g''' h3/2, f^3(g''''/48+(g'')^2/8)h2^2, and f^3(g'''''/48+g''g'''/4)h2h3. Expanding the logarithmic derivatives gives exactly P3,P4,P5 above. Differentiating the expression for P4 gives P4'=3(f'/f)P4+P5. Multiplication by f yields the displayed polynomial identity. Since all final expressions are polynomial in entire derivatives, analytic continuation extends them across every zero; f identically zero is immediate. Direct differentiation of the polynomial P4 also verifies fP4'-3f'P4=fP5 without division. These formulas supply no global logarithm and require no zero-free hypothesis.")),
            Paragraph(Text("Weighted norms with exact Gaussian and factorial normalization. Define ||P||_3^2=(3/pi)integral_C |P(c)|^2 exp(-3|c|^2)d^2c. The change t=sqrt(3)c gives ||P(t/sqrt(3))||_center^2=||P||_3^2, and ||c^k||_3^2=k!/3^k. Orthogonality of Bargmann monomials gives ||h3||^2=2!/6+3!/54=4/9; ||h2^2||^2=4!+4(2!2!)+4!=64; and, since h2h3=(u^4v+(2/3)u^2v^3-v^5/3)/sqrt(6), ||h2h3||^2=4+8/9+20/9=64/9. It follows that ||F_{a,3}||^2=(4/9)||P3||_3^2, ||F_{a,4}||^2=64||P4||_3^2 and ||F_{a,5}||^2=(64/9)||P5||_3^2. The center Gaussian is part of every norm; evaluating only at center vacuum would change the assertion.")),
            Paragraph(Text("Why the projected identities and weighted integrability hold for every complex l2 input. Cauchy-Schwarz gives |f(z)|<=||a||exp(|z|^2/2), hence f is entire. The three-mode orthogonal coordinate change is unitary on completed Fock space and maps a tensor3 to F_a, of squared norm ||a||^6. For truncations a_L, their tensor cubes converge in Hilbert norm, while the corresponding f_L and every fixed derivative converge uniformly on compact disks by reproducing estimates and Cauchy's formula. The projected polynomial identities hold for f_L. Orthogonal projection is bounded; projected Hilbert convergence and continuous center evaluation therefore identify the limiting coefficients with Pj(f)(t/sqrt(3)). The degree-three, four and five invariant spaces are exactly the one-dimensional lines already identified, so these are the whole projected vectors. Their norms are finite because they are bounded projections of F_a. This proves the weighted integrability of the displayed derivative combinations without assuming that differentiation is bounded on H or that the individual derivatives belong to H. Infinite support, arbitrary phases, unbounded mean photon number, and the full center coordinate remain in scope.")),
            Paragraph(Text("Evidence and literature boundary for this package. The same-function identities, relative-sector estimates and physical perturbation arguments here and in Entropy are independently source-assessed analytic mathematics pending formalization. The analytic evidence includes independent source assessment of the pinned owner definitions and their model correspondence; source reading is not kernel verification. No successful Pro source audit of those owners is part of this evidence. Further literature checks preserve exact settings: arXiv:1301.5229, Section III and equations (11)-(14), has a vacuum second input; arXiv:2411.03423v1, Lemma 6 and Theorem 7, uses two vacuum environment modes in its two-copy overlap mechanism. Neither supplies this three-copy two-photon estimate. The coherent-transform convex-functional theorem in arXiv:2210.14798, Theorem 1, does not identify its phase-space integral with 2p3-3s p2+(13/16)s^3. No such missing bridge is assumed. These bounded checks make no worldwide novelty or priority claim.")),
            Paragraph(Text("Attainment and variation for the balanced two-photon channel (A1–A6). The coefficient localization and weak-profile splitting proved here feed the attainment and variational argument in the Entropy owner. Throughout H=ℓ²(ℕ;ℂ), with Bargmann basis eₙ(z)=zⁿ/√(n!), and no support, rank, energy or photon-moment restriction is imposed. These are readable analytic proofs, with the physical/library identifications made explicit; the new attainment statements and the cited D/P/T analytic dependencies still require their exact native realization. Existing Lean declarations and their Describes retain their own narrower scopes.")),
            Paragraph(Text("The physical map is V f(z,w)=f((z+w)/√2)(w−z)²/(2√2), with z retained and w discarded. It is the balanced specialization of BeamSplitter.rotate, beamSplitter, fockExpansion and beamUnitary_fock with environment e₂: the orthogonal coordinates x=(z+w)/√2, y=(w−z)/√2 turn it into f(x)e₂(y). Thus V is an isometry on the completed space. Write Cₐ for its occupation coefficient operator, (Cₐ)ᵢⱼ=cᵢⱼaᵢ₊ⱼ₋₂. For N=i+j≥2, cᵢⱼ=√(binom(N,i)/2ᴺ)·((i−j)²−N)/√(2N(N−1)); set it to zero when N<2 or an index is invalid, and take negative input indices as zero. Indeed expanding (z+w)ᴺ⁻²(w−z)² gives binom(N,i)((N−2i)²−N)/(N(N−1)); the occupation factorials give exactly the displayed coefficient, including its sign. In particular Cₐ is symmetric. The orthogonal anti-diagonals and isometry give ‖Cₐ‖₂=‖a‖ and σₐ=CₐCₐ*=Φ(|a⟩⟨a|), positive trace class with Tr σₐ=‖a‖². Here ‖·‖₂ and ‖·‖₁ denote Hilbert–Schmidt and trace norms; Tr is the analytic trace-class trace.")),
            Paragraph(Text("This output is the actual pureAttenuatorOperator, not a chosen spectrum: pureOutputVector supplies precisely its discarded-mode columns, whose rank-one mixture is CₐCₐ*. For a general source DensityOperator, positivity and the full occupation diagonal sum one imply a normal trace-class density. The columns of its positive square root give its rank-one sum in trace norm, and outputVector/attenuatorOperator apply the same channel to this sum. The normal channel is Φ(T)=Tr_w(VTV*), with its actual bounded positive unital adjoint Φ*(K)=V*(K⊗Id)V. For all u,v∈H and bounded K, Tr[KΦ(|u⟩⟨v|)]=⟨v,Φ*(K)u⟩ (inner products are conjugate-linear in the first variable). These completed vectorization, trace-class and trace-pairing identifications are analytic joins to the source definitions; they are explicit outstanding native bridges, rather than consequences of merely displaying those definitions.")),
            Paragraph(Text("A1. Compactness of both fixed finite occupation restrictions. Let P_L project onto occupations 0,…,L, where L stays fixed. Orthogonal anti-diagonals give ‖C_bP_L‖₂²=Σₖ≥₀w_L(k)|bₖ|², where w_L(k)=Σ₀≤ⱼ≤min(L,k+2)|cₖ₊₂₋ⱼ,ⱼ|² and 0≤w_L(k)≤1. With N=k+2≥2 and 0≤j≤N, 0≤(N−2j)²≤N² implies |(N−2j)²−N|≤N(N−1). Hence |c_N−j,j|²≤binom(N,j)N(N−1)/(2·2ᴺ)≤Nʲ⁺²/(2j!2ᴺ). Summing gives the explicit bound w_L(k)≤(1/8)(Σⱼ₌₀ᴸ1/j!)(k+2)ᴸ⁺²2⁻ᵏ→0. The bound depends on L; no uniformity as L→∞ is used.")),
            Paragraph(Text("Let Q_K truncate input coordinates at K. The maps b↦C_(Q_Kb)P_L have finite-dimensional range, and the squared norm of the omitted map is at most supₖ>K w_L(k)→0. Thus b↦C_bP_L is an operator-norm limit of finite-rank maps from H to S₂, and is compact. Symmetry cᵢⱼ=cⱼᵢ gives the identical weighted estimate and approximation for b↦P_LC_b. Both maps therefore take every bounded weakly null sequence to zero in S₂. The full map b↦C_b is an isometry on an infinite-dimensional space and is not compact. Neither a varying L nor a discarded infinite tail occurs in this argument.")),
            Paragraph(Text("A2. Trace-class decoupling of a weak profile. Fix any a∈H and any bounded sequence rₙ⇀0. First suppose a is supported in 0,…,M, so Cₐ is supported in rows and columns 0,…,M+2. For L=M+2, Schatten Hölder and A1 give ‖CₐC_rₙ*‖₁=‖Cₐ(C_rₙP_L)*‖₁≤‖Cₐ‖₂‖C_rₙP_L‖₂→0. For a general a, choose finite-support b approaching a. The error is at most ‖C_(a−b)C_rₙ*‖₁≤‖a−b‖‖rₙ‖, uniformly in n. Taking first n→∞ and then b→a proves the same conclusion. Its adjoint C_rₙCₐ* has the same trace norm.")),
            Paragraph(Text("The remainder outputs vanish against every compact output test K. For finite occupation compression, |Tr(P_LKP_Lσ_rₙ)|≤‖K‖Tr(P_Lσ_rₙ)=‖K‖‖P_LC_rₙ‖₂²→0. For arbitrary compact K, ‖K−P_LKP_L‖→0, while ‖σ_rₙ‖₁=‖rₙ‖² is uniformly bounded. Approximation therefore gives Tr(Kσ_rₙ)→0. K need not be positive or finite rank. This is convergence against compact operators; the remainder outputs need not tend to zero in trace norm.")),
            Paragraph(Text("Set A=σₐ and Rₙ=σ_rₙ. The exact quadratic output expansion reads σ_(a+rₙ)=A+Rₙ+εₙ, with εₙ=CₐC_rₙ*+C_rₙCₐ*→0 in S₁. On bounded trace-norm sets, telescoping products give |Tr(Tʲ−Sʲ)|≤jMʲ⁻¹‖T−S‖₁ for j=2,3, when the operator norms are at most M. Every product has a trace-class factor and otherwise bounded factors. It remains to expand A+Rₙ without assuming commutativity. The quadratic cross traces are Tr(ARₙ)+Tr(RₙA)=2Tr(ARₙ)→0. The six cubic words are A²Rₙ, ARₙA, RₙA² and ARₙ², RₙARₙ, Rₙ²A; cyclicity gives respectively 3Tr(A²Rₙ) and 3Tr(ARₙ²). The compact tests with A,A² kill the first mixed traces. Positivity and Rₙ²≤‖Rₙ‖Rₙ give 0≤Tr(ARₙ²)≤‖Rₙ‖Tr(ARₙ)→0. Thus pⱼ(a+rₙ)=pⱼ(a)+pⱼ(rₙ)+o(1), j=2,3, where pⱼ(b)=Tr σ_bʲ. All infinite rows and columns remain present.")),
            Paragraph(Text("For unnormalized b write s(b)=‖b‖², e₂(σ_b)=(s(b)²−p₂(b))/2 and E(b)=e₃(σ_b)=(s(b)³−3s(b)p₂(b)+2p₃(b))/6. The elementary symmetric sums converge absolutely for positive trace-class operators (e₃≤s³/6). Weak convergence gives s(a+rₙ)=s(a)+s(rₙ)+o(1). Substitution of the moment splitting into these Newton identities yields E(a+rₙ)=E(a)+E(rₙ)+s(a)e₂(σ_rₙ)+s(rₙ)e₂(σₐ)+o(1). Both unnormalized cross masses survive, including when a or a remainder is zero. This is the physical splitting used below; neither cross term can be dropped.")),
            Paragraph(Text("The trace-ideal estimates have existing supplier homes in D5/S3/Quantum/Analysis/TraceClass: GeneralProduct.isTraceClass_mul_of_isHilbertSchmidt, IdealNorm.traceNorm_mul_le_of_isHilbertSchmidt and traceNorm_mul_mul_le, TraceAlgebra.trace_mul_cycle, Pairing.tracePairingContinuousLinearMap, and Compact.isCompactOperator_of_isTraceClass. Their attributed physlib source is b9043cc548ef6d63a28454cf3a57fb12a0c2e142 (Tom Ole Diem, Apache 2.0). They supply norm, product, trace and compactness tools, rather than the new physical coefficient or splitting theorems. Pinned Mathlib supplies compact-map composition and operator-norm closure, and real bounded-bilinear differentiation. Future native work must reuse exact matching statements and establish the actual channel bridges; no duplicate binding theorem is introduced here.")),
            Paragraph(Text("Conditional completed-channel structural package R1-R3. All statements in this addendum are analytic prose pending native formalization. They use H=l2(N;C), e_n(z)=z^n/sqrt(n!), the inner product conjugate-linear in its first argument, and exactly the balanced Fock-two channel Phi(T)=Tr_w U(T tensor |e2><e2|)U^*, with (U(f tensor e))(z,w)=f((z+w)/sqrt(2))e((w-z)/sqrt(2)). Thus V f=U(f tensor e2)=f((z+w)/sqrt(2))(w-z)^2/(2sqrt(2)), sigma_a=Phi(|a><a|)=C_a C_a^*, and Phi^*(K)=V^*(K tensor Id)V. The bounded normal-channel extension to all complex trace-class T and this actual trace-dual adjoint are the intended interfaces, not a newly assigned output spectrum. Write E(b)=e3(sigma_b), I=inf_{||b||=1}E(b), q=Tr(sigma_a^2), p3=Tr(sigma_a^3), mu=q-p3, B=Phi^*(sigma_a-sigma_a^2), and A=(1/2)Id-sigma_a. Assume I<1/32 and an actual unit global minimizer a. No initial energy, support, output-rank, coefficient-phase or moment hypothesis is imposed.")),
            Paragraph(Text("Exact attainment/variational prerequisites for the conditional argument. A1 is compactness, for each fixed finite occupation projection P_L, of b -> C_b P_L and b -> P_L C_b from H to S2; the full map b -> C_b is an isometry, not a compact map. A2 says that, for every fixed b and every bounded weakly-null r_j, ||C_b C_rj^*||_1 ->0 and Tr(K sigma_rj)->0 for every compact output K; it also supplies the unnormalized quadratic/cubic moment splitting. A3-A4 give 25/864<=I<=1/32 and, for every minimizing sequence, a strongly convergent unit-minimizing subsequence after maximizing coherent displacements and phases. In that representative a_0=sqrt(m(a))>0 and a_1=0, where m(b)=sup_alpha |<coherent(alpha),b>|^2. This existence and gauge package is a separate analytic prerequisite: the conditional argument here does not supply its full proof, and the existing Lean declarations do not certify it. R1, the general spectral-range part of R2 and R3 do not require that centered gauge.")),
            Paragraph(Text("A5-A6 in the exact physical domain. A5 gives real Frechet smoothness of the bounded trace-polynomial E, the actual trace-dual Phi^*, compactness of Phi^*(K) for every compact output K, and Ba=mu a. At unit a, DE(a)[h]=2 Re<h,[e2(sigma_a)Id-B]a>; at an unnormalized input the exact formula is DE(a)[h]=2 Re<h,[e2(sigma_a)Id-||a||^2 Phi^*(sigma_a)+Phi^*(sigma_a^2)]a>, so the unit formula must not be used without its normalization. A6 states, for every complex h with <a,h>=0, X_h=Phi(|h><a|+|a><h|) and <h,Bh>+Tr(A X_h^2)<=mu||h||^2. For the same negative minimizer, the earlier physical purity and spectral arguments give q<=3/8, ||sigma_a||<1/2, 0<=B<=mu Id and B positive compact. In particular epsilon=1/2-||sigma_a||>0 and A>=epsilon Id. These are conditional analytic premises from the entire A1-A6 package and its D/P/T dependencies, pending their native joins. Neither an abstract compact operator nor purity alone supplies these same-input hypotheses. All traces below are analytic S1 traces, never the total algebraic LinearMap.trace outside finite dimension.")),
            Paragraph(Text("R1: the actual Weyl multiplier on every complex trace-class input. Let D(xi)=exp(xi c^*-conj(xi)c) denote the bounded strongly continuous Weyl unitary in the source convention, and chi_T(xi)=Tr(T D(xi)). This notation does not differentiate an unbounded exponential. The completed splitter identity gives U^*(D(xi) tensor Id)U=D(xi/sqrt(2)) tensor D(-xi/sqrt(2)). Pairing this bounded identity with T tensor |e2><e2|, and using the defining partial trace, gives chi_Phi(T)(xi)=chi_T(xi/sqrt(2))<e2,D(-xi/sqrt(2))e2>. It holds for arbitrary, possibly non-self-adjoint T in S1, with no photon moments. The environmental sign follows from the actual repository rotation.")),
            Paragraph(Text("The finite environmental coefficient and its two zero circles. In Bargmann coordinates, D(zeta)e2(z)=exp(-|zeta|^2/2+zeta z)(z-conj(zeta))^2/sqrt(2). Its normalized z^2 coefficient is <e2,D(zeta)e2>=exp(-|zeta|^2/2)(1-2|zeta|^2+|zeta|^4/2). Therefore chi_Phi(T)(xi)=chi_T(xi/sqrt(2))exp(-|xi|^2/4)L2(|xi|^2/2), where L2(t)=1-2t+t^2/2. The sign in the environmental displacement disappears here because this particular characteristic is radial. The only zeros have |xi|^2=4-2sqrt(2) or 4+2sqrt(2). Their complement is dense; it is not necessary that the multiplier be everywhere nonzero.")),
            Paragraph(Text("Continuity across the circles and Weyl uniqueness. For finite-rank F, strong continuity of D and its matrix coefficients makes chi_F continuous. Finite-rank trace-norm approximation gives |Tr((T-F)D(xi))|<=||T-F||_1 uniformly in xi, hence chi_T is continuous for every complex T in S1. If Phi(T)=0, the multiplier identity makes chi_T(xi/sqrt(2)) zero off the two circles. Scaling and continuity give chi_T=0 everywhere. Fourier-Weyl Plancherel, with measure d^2xi/pi in this complex displacement normalization, is injective on S2; S1 is contained in S2. Applying it to this same T proves T=0. Thus the actual channel is injective on all S1, including non-self-adjoint perturbations. This use of Weyl uniqueness supplies no lower bound for an inverse channel norm.")),
            Paragraph(Text("R1: simplicity needs both complex directions. Suppose h is complex-perpendicular to a and Bh=mu h. A6 implies Tr(A X_h^2)<=0. Since X_h=X_h^* is S1 and A>=epsilon Id, trace-ideal cyclicity gives Tr(A X_h^2)=||A^(1/2)X_h||_2^2>=epsilon||X_h||_2^2, so X_h=0. Apply A6 separately to ih, which is again perpendicular and a mu-eigenvector, to obtain X_ih=0. For Y=Phi(|h><a|), complex linearity and adjoint preservation give X_h=Y+Y^* and X_ih=iY-iY^*. Both equations force Y=0. Channel injectivity gives |h><a|=0; applying it to the unit a gives h=0. Every mu-eigenvector of self-adjoint B splits into a multiple of a and such an h. Hence ker(B-mu Id)=C a. Compactness alone would not prove this simplicity.")),
            Paragraph(Text("R1: a gap for this fixed self-consistent operator. B preserves the complex perpendicular a^perp. Its positive compact restriction has norm strictly below mu: if the norm equalled the nonzero mu, compact self-adjoint spectral theory would give a further mu-eigenvector in a^perp, contradicting simplicity. Thus delta_a=mu-||B restricted to a^perp||>0 and <h,Bh><=(mu-delta_a)||h||^2 there. Newton gives 6I=1-q-2mu. The strict inequality I<1/32 implies mu>13/32-q/2, and q<=3/8 implies mu>7/32. There is no numerical, input-uniform or all-minimizer uniform delta_a. Simplicity concerns the B generated by this a; a different physical input generates a different B, so no uniqueness of minimizers follows.")),
            Paragraph(Text("R2: auxiliary environmental transfer for arbitrary bounded output K. For any environmental vector e put J_e b=U(b tensor e) and Phi_e^*(K)=J_e^*(K tensor Id)J_e. The mixed map (e,f) -> J_e^*(K tensor Id)J_f is bounded sesquilinear, with norm at most ||K||||e||||f|| because ||J_e||=||e||. After realification this is a bounded real-bilinear operation. No positivity, compactness, smooth symbol, finite rank or moment assumption on K is needed. The target channel remains Phi=Phi_e2 throughout; the other environments are auxiliary terms in an identity.")),
            Paragraph(Text("Repository-sign displacement transfer. The source rotation sends displacement labels (alpha,beta) to ((alpha-beta)/sqrt(2),(alpha+beta)/sqrt(2)). A signal displacement (alpha,0) gives output labels (alpha/sqrt(2),alpha/sqrt(2)); an environment displacement (0,-alpha) gives (alpha/sqrt(2),-alpha/sqrt(2)). Their retained labels agree and partial trace removes the differing discarded displacements. Thus Phi_e(D(alpha)T D(alpha)^*)=Phi_{D(-alpha)e}(T)=D(alpha/sqrt(2))Phi_e(T)D(alpha/sqrt(2))^* for every T in S1. Rank-one identities extend by polarization and trace-norm continuity. Trace duality gives D(alpha)^*Phi_e^*(K)D(alpha)=Phi_{D(-alpha)e}^*(K) for every bounded complex K. No Weyl phase survives conjugation. The attenuator paper uses the opposite environmental sign in its splitter convention; even e2 parity does not permit silently changing the sign of a displaced auxiliary environment.")),
            Paragraph(Text("R2: real operator-norm C-infinity from a known finite Fock vector. For e=e2, D(-alpha)e2(z)=exp(-|alpha|^2/2-alpha z)(z+conj(alpha))^2/sqrt(2). Every real derivative is a polynomial in z, alpha and conj(alpha) times the same exponential. On |alpha|<=R, each finite derivative order has squared Bargmann integrand bounded by C(1+|z|)^M exp(-|z|^2+2R|z|), which is integrable. Norm differentiation under the integral proves that alpha -> D(-alpha)e2 is C-infinity from R^2 into H. The identical argument works for every finite Fock polynomial. Composing with the bounded sesquilinear map proves that alpha -> D(alpha)^*Phi^*(K)D(alpha) is C-infinity in operator norm for every bounded K. All smoothness here is real smoothness, not holomorphy, and D(alpha) itself is never differentiated in operator norm.")),
            Paragraph(Text("R2: isolate the spectral range before differentiating any unknown eigenvector. Now, only for this spectral step, assume K compact self-adjoint and let L=Phi^*(K). A5 makes L compact self-adjoint. A nonzero eigenvalue lambda has an isolated finite-rank spectral projection P. Choose a resolvent contour Gamma enclosing lambda and no other spectrum. L_alpha=D(alpha)^*L D(alpha) is norm-C-infinity by the preceding argument. Inversion is C-infinity on the invertible elements of the complete operator algebra; for R=(z Id-L_alpha)^(-1), its first derivative is R(dL_alpha)R and higher derivatives are finite products with uniformly bounded resolvents on compact contour and parameter sets. Consequently P_alpha=(2pi i)^(-1) integral_Gamma (z Id-L_alpha)^(-1)dz is norm-C-infinity. Unitary conjugacy gives P_alpha=D(-alpha)P D(alpha). No regularity of a lambda-eigenvector has been assumed in obtaining this projection.")),
            Paragraph(Text("Finite smooth seeds give the whole eigenspace, without simplicity or a gauge assumption. Finite Fock vectors form a dense linear subspace. Its image under P is a dense linear subspace of finite-dimensional Ran P, so equals Ran P. Choose finitely many such vectors v_j whose Pv_j span Ran P. The exact identity D(-alpha)Pv_j=P_alpha D(-alpha)v_j expresses the left orbit using two already smooth factors. Every fixed linear combination, hence every vector in the lambda-eigenspace, has a norm-C-infinity displacement orbit. These finite seed vectors do not restrict the support of the eigenvector. R1 simplicity is needed only for the optional explicit centered formula: with P=|a><a| and a_0=sqrt(m(a))>0 real, Pe0=sqrt(m(a))a and D(-alpha)a=m(a)^(-1/2)P_alpha D(-alpha)e0. That last formula must not be asserted for an arbitrary uncentered phase choice.")),
            Paragraph(Text("The zero-eigenvalue boundary and the actual minimizer. Lambda=0 is excluded: its kernel need not be an isolated finite-dimensional spectral range. Compactness and self-adjointness of K enter only the spectral argument, while arbitrary-bounded-K norm smoothness holds without them. In particular Phi^*(Id)=Id, so the argument does not claim that all bounded K have compact images. For the same hypothetical minimizer take K=sigma_a-sigma_a^2, compact self-adjoint, and lambda=mu>7/32. Its eigenvector a therefore has a norm-C-infinity displacement orbit, without any initial photon-domain assumption.")),
            Paragraph(Text("Exact pure Wirtinger derivative in the occupation basis. This coordinate and domain argument applies to every nonzero-eigenvalue eigenvector just obtained, including the minimizer; denote it by a. Set F(alpha)=D(-alpha)a, alpha=x+iy, and partial_alpha=(partial_x-i partial_y)/2. Its norm derivatives now exist, so bounded coordinate evaluation commutes with them. In the conjugate-linear-first convention, F(alpha)_n=<D(alpha)e_n,a>; transferring differentiation to that first slot changes partial_alpha into partial_conj(alpha). Differentiating the known finite-Fock orbit yields (partial_alpha^k F(0))_n=(-1)^k sqrt(n!/(n-k)!)a_(n-k) for n>=k, and zero for n<k. Equivalently the pure alpha derivative at zero of exp(-|alpha|^2/2-alpha z)f(z+conj(alpha)) is (-z)^k f(z). There is no conjugation of a_(n-k) and no missing factor two. Mixed Wirtinger derivatives have additional terms and are not being identified with this pure derivative. The computation identifies an already existing norm derivative; it does not apply an unbounded creation operator to an arbitrary starting vector.")),
            Paragraph(Text("Parseval and every number-operator domain. Parseval gives the exact equality ||partial_alpha^k F(0)||^2=sum_{j>=0}((j+k)!/j!)|a_j|^2<infinity for every integer k>=0. For the number operator N e_j=j e_j and any integer r>=0, take k=2r and use (j+1)^(2r)<=product_{ell=1}^{2r}(j+ell); k=0 handles r=0. Therefore sum_j(j+1)^(2r)|a_j|^2<infinity, exactly a in Dom((N+1)^r). Arbitrarily large r give rapid occupation coefficients. In the standard Hermite identification with the Schrodinger oscillator, these are Schwartz vectors: every word in creation and annihilation has square-summable coefficients; thus all polynomially weighted derivatives are L2, and Sobolev estimates supply all Schwartz seminorms. This Hermite/Schwartz identification is an analytic bridge, still to be supplied natively if a formal statement names SchwartzMap. No exponential decay, analytic-vector property, finite support, finite output rank, uniform moment bound or tail deletion is concluded.")),
            Paragraph(Text("Primary source and prior-method scope for R1-R2. The actual displacement and splitter conventions are in BeamSplitter and DisplacementCovariance at immutable published revision bc0d5339476df8b41d58d7cde040a82266a9f416, including beamUnitary_fock, beam_displacement and partialTrace_pairDisplacement on the full completion. Kiukas, Lahti, Schultz and Werner, Characterization of informational completeness for covariant phase space observables, https://arxiv.org/html/1204.3188v1, Section 2 and Proposition 4, supply classical Fourier-Weyl Plancherel and the continuous-transform/dense-complement mechanism, including complex trace-class operators. Their phase-space observable is not Phi: the actual channel multiplier is derived above. Bastianoni, Cordero and Nicola, Decay and Smoothness for Eigenfunctions of Localization Operators, https://arxiv.org/html/1902.03413v2, Theorem 3.10 and Remark 3.11, prove Schwartz eigenfunction regularity under Schwartz-window and weighted modulation-symbol hypotheses. Those symbol hypotheses have not been established for B, so that theorem is not imported; the direct environmental transfer and finite-seed spectral argument supply the needed regularity here. No novelty is claimed for harmonic analysis or spectral smoothing methods.")),
            Paragraph(Text("Positive overlap inherited from the entire prerequisite packages. Zixuan He, The energy cost of optical noise, version 1.0, https://zenodo.org/records/23629201, DOI 10.5281/zenodo.23629201, Theorem 8 and Appendix F already establish all-normal balanced Fock purity, the bounded copy kernel and coherent equality for n>=2. Appendix K.5 gives coherent-orbit compactness when difference-vacuum overlap tends to one; K.6 contact-family assumptions do not classify every pure-e2 e3 minimizer. Ramos, Eigenfunctions, Free Boundaries, and Time-Frequency Localization, https://arxiv.org/html/2607.21590v2, Section 7, gives Weyl profiles and concentration-compactness for a quadratic Gaussian localization functional with a set-measure constraint, not this degree-six physical functional. Frank, Nicola and Tilli, The generalized Wehrl entropy bound in quantitative form, https://arxiv.org/html/2307.14089v3, Theorem 3 and Remarks 4, compare convex Husimi integrals for positive trace-one operators; the P-package uses its stated normalization, but no equality with the physical cubic cycle term or exclusion of our minimizer follows. These are positive prior overlaps with precise applicability limits, not claims of worldwide novelty or absence.")),
            Paragraph(Text("Channel source and unresolved scope. Van Herstraeten, Guha and Cerf, https://arxiv.org/html/2312.15623v2, Section IV, equations (44)-(45), give the actual Fock channel and arbitrary-environment displacement covariance, with the splitter-sign difference just stated. Their Conjecture 1 remains the all-n/all-eta minimum-output-entropy question in that version. R1-R3 are conditional analytic consequences for the same hypothetical negative minimizer. They do not prove E>=1/32, unrestricted balanced-Fock-two entropy, the countable spectral/ENNReal bridge or Conjecture 1; they construct no negative physical input and classify no minimizer. The companion Entropy narrative retains the whole real-Hessian proof and every same-function center/relative-sector obligation. All infinite coefficients and all complex directions remain in scope.")),
            Paragraph(Text("The one-mode space is lp(Function.const(Nat,Complex),2) and the two-mode space is lp(Function.const(Nat,lp(Function.const(Nat,Complex),2)),2). The occupation vector at n is lp.single 2 n (Complex.ofReal 1). All state and environment supports are unrestricted. conjStarAlgEquiv is Mathlib LinearIsometryEquiv.conjStarAlgEquiv, mapping T to U composed with T and U inverse. Function names are the displayed Lean definitions or the explicitly stated Mathlib operations. Application parentheses retain grouping; NatSub is truncated natural subtraction, val is the natural value of a finite index, toReal is the natural-to-real cast and Complex.ofReal is the real-to-complex cast. Fields carrying proofs are omitted from constructor formulas; when a named proof parameter occurs in a function signature it appears as an argument of that function.")),
            Paragraph(Text("T1: the complete complex quadratic family. Keep the physical map and increasing-triple exterior convention above. For arbitrary A,B,C in C, put xi=A e0+B e1+C e2, s=|A|^2+|B|^2+|C|^2, R=|B|^2+|C|^2 and G(xi)=e3(C_xi C_xi^*)-s^3/32. Expanding the actual isometry on f(z)=A+Bz+Cz^2/sqrt(2) gives its full nonzero occupation block C_xi=[[0,0,A/2,sqrt(6)B/4,sqrt(6)C/4],[0,-A/sqrt(2),-B/(2sqrt(2)),0,0],[A/2,-B/(2sqrt(2)),-C/2,0,0],[sqrt(6)B/4,0,0,0,0],[sqrt(6)C/4,0,0,0,0]]. Every other row and column vanishes. The three occupied anti-diagonals contribute |A|^2, |B|^2 and |C|^2 to the squared Hilbert-Schmidt norm, so Tr(C_xi C_xi^*)=s. In particular G(lambda xi)=|lambda|^6 G(xi); the subtraction is ||xi||^6/32 even before normalization. These statements include all phases and zero coefficients.")),
            Paragraph(Text("Complete third-minor calculation by unitary compression. Set x=A/2, y=-A/sqrt(2), z=-B/(2sqrt(2)), w=-C/2, u=sqrt(6)B/4, v=sqrt(6)C/4 and Delta=yw-z^2. If R>0, a unitary U on coordinates 3,4 sends (u,v)^T to (r,0)^T, r=sqrt(3R/8). The unitary congruence diag(I3,U) C_xi diag(I3,U)^T preserves singular values: its right transpose times its complex conjugate is the identity. Its only nonzero block is M=[[0,0,x,r],[0,y,z,0],[x,z,w,0],[r,0,0,0]]. Consequently every minor containing the remaining zero coordinate vanishes, and the full exterior Hilbert-Schmidt norm of the original five-by-five matrix equals that of M. The signed cofactor matrix of M, in index order 0,1,2,3, is [[0,0,0,-r Delta],[0,-r^2 w,r^2 z,-r x z],[0,r^2 z,-r^2 y,r x y],[-r Delta,-r x z,r x y,-x^2 y]]. This lists all sixteen complementary third minors: cofactor (i,j) is (-1)^(i+j) times the determinant with row i and column j omitted, in increasing order. Thus the seven displayed nonzero monomial types -r Delta,-r^2 w,r^2 z,-r x z,-r^2 y,r x y,-x^2 y have multiplicities 2,1,2,2,1,2,1; the other five positions vanish. There is no factorial multiplier. Cauchy-Binet therefore gives e3(C_xi C_xi^*)=2r^2|Delta|^2+r^4(|y|^2+2|z|^2+|w|^2)+2r^2|x|^2(|y|^2+|z|^2)+|x|^4|y|^2. This accounts for the entire original hundred-minor sum by an exterior-unitary equivalence, including every multiplicity and cofactor sign, rather than checking selected minors.")),
            Paragraph(Text("The factorization and every degenerate fiber. Substitute Delta=(2sqrt(2)AC-B^2)/8 and r^2=3R/8 into the complete minor sum. After subtracting s^3/32 it gives 256G(xi)=R^3+3R|B^2-2sqrt(2)AC|^2-6|A|^2R|C|^2. Expanding the bracket R^2+3|B^2-2sqrt(2)AC|^2-6|A|^2|C|^2 yields 4|B|^4+2|B|^2|C|^2+|C|^4+18|A|^2|C|^2-12sqrt(2)Re(B^2 conjugate(AC)). The same expansion is 2|sqrt(2)B^2-3AC|^2+2|BC|^2+|C|^4. Hence the exact identity is 256G(xi)=R(2|sqrt(2)B^2-3AC|^2+2|BC|^2+|C|^4). If R>0, vanishing would force C=0 from |C|^4, then B=0 from the square, a contradiction. If R=0, B=C=0 and the original matrix directly has e3=|A|^6/32; this includes A=0 and uses no choice of coupling direction or division by zero. Thus G>=0 with equality exactly B=C=0. For example e2 has physical spectrum (3/8,3/8,1/4), so e3=9/256 and G=1/256, consistent with the complete degree-six identity.")),
            Paragraph(Text("T2: the exact completed pure rank-through-five characterization. For every nonzero a in complex l2 with Bargmann function f, rank(C_a C_a^*)<=5 if and only if f(z)=exp(alpha z)P(z) for some alpha in C and a nonzero polynomial P of degree at most two. Reuse the entire-function proof in 'Finite output rank forces an exponential polynomial' and the following translation/Cayley-Hamilton paragraph: finite operator rank equals finite separation rank, (partial_z-partial_w)^2[(z-w)^2 f(z+w)]=8f(z+w), and the finite-dimensional compact-open translation space is derivative invariant. This supplies every completed-vector hypothesis, without bounded differentiation on Fock space. Reuse 'Ranks add across distinct exponentials' and 'All degrees in one polynomial block' for the independent exponential blocks and the nonzero triangular minor, regardless of lower coefficients. Every nonzero block has rank at least three, including degrees zero, one and two as computed above. Two distinct exponential blocks already have rank at least six. For a single block of degree m>=5 the top anti-diagonal has m+3 positions and at most two zeros, hence rank>=m+1>=6. The only remaining excluded degrees are m=3 and m=4: N=m+2 is respectively 5 or 6, and the equation (N-2i)^2=N has no integer solution. All six or seven top entries survive, giving rank exactly six or seven. Thus rank<=5 forces precisely one exponential block of degree<=2. Engert's measurable-function theorem is classical context for the already supplied direct entire-function argument; it is not imported with an unstated holomorphic or pointwise hypothesis.")),
            Paragraph(Text("Converse, exact displacement, ranks and equality. In the source convention D(gamma)f(z)=exp(-|gamma|^2/2+gamma z)f(z-conj(gamma)), so D(-alpha)[exp(alpha z)P(z)]=exp(|alpha|^2/2)P(z+conj(alpha)). Both the plus conjugate shift and the norm prefactor are essential. The completed identities beam_displacement and partialTrace_pairDisplacement conjugate the actual output by D(-alpha/sqrt(2)); they preserve its rank, e3, input norm and G. Thus the converse follows from the T1 matrix, which has rank at most four. More exactly, when R=0 a nonzero constant has rank three. When R>0 the endpoint pivot gives rank M=2+rank([[y,z],[z,w]]); its Schur correction to this middle block is zero. This middle block is nonzero. If C=0 and B!=0 its determinant is -B^2/8!=0, giving rank four. If C!=0, the rank is three exactly when B^2=2sqrt(2)AC, otherwise four. These include all double-root quadratics and all complex degeneracies. Therefore every nonzero pure output of rank<=5 has rank three or four, and no pure output has rank five. Applying the homogeneous T1 identity after displacement gives G(a)>=0 throughout this class, with equality exactly for nonzero scalar coherent vectors. In particular noncoherent rank-three inputs also have strict G>0. The original input exp(alpha z)P(z) generally has infinite Fock support; polynomial support is obtained by an exact unitary displacement forced by the rank condition, not by an input cutoff.")),
            Paragraph(Text("An interior physical example for the additional exclusion. The normalized input a=(8e0+e2)/sqrt(65) has output rank four, q=Tr(sigma^2)=50443/135200, largest eigenvalue 32/65, coherent overlap maximum m=64/65, and G=1153/(256*65^3)>0. These values follow from the actual T1 matrix. Before normalization its isolated coefficient eigenvalue is -4sqrt(2); the remaining nonzero real symmetric block is N=[[0,4,sqrt(6)/4],[4,-1/2,0],[sqrt(6)/4,0,0]], whose absolute row sums are at most 4+sqrt(6)/4<5<4sqrt(2). Thus its squared eigenvalues are below 32. Also Tr N^2=33, Tr N=-1/2, e2(N)=-131/8 and det N=3/16. Hence e2(N^2)=17173/64 and Tr N^4=17675/32; adding 1024 and dividing by 65^2 gives q. For the coherent maximum, |8+z^2/sqrt(2)|<=8+|z|^2/sqrt(2), and exp(-x)(8+x/sqrt(2))^2 decreases for x>=0 because its derivative is exp(-x)(8+x/sqrt(2))(sqrt(2)-8-x/sqrt(2))<0. Equality at z=0 gives m. T1 gives the gap numerator 2*24^2+1=1153. The deficit 3/8-q=257/135200 is positive and exceeds 1/[10(2^20+1)]; q>37/100>(17-5sqrt(5))/16, 32/65<1/2 and 64/65<2^20/(2^20+1). This is an actual point inside the necessary scalar region, now excluded by the quadratic identity. It illustrates the uncountable quadratic family and does not assert realizability of arbitrary spectra.")),
            Paragraph(Text("Scope of T1-T2. These analytic consequences, together with T3 in Entropy, remain pending formalization. The existing completed-source Lean declarations retain their own statements and do not kernel-prove the new conclusions. Finite determinant arguments are credited in Entropy, and the physical purity/kernel/coherent-equality prerequisite is positively attributed there to He. The cited literature establishes the stated overlaps and exact hypotheses, without an exhaustive novelty or priority claim. The all-input physical e3 bound and the original all-n/all-eta entropy conjecture remain open.")),
            Node("ProbabilityVector", Disp(new Formula.Aligned([All("p",Prob(),Seq(Call("weight",P),Colon,Fn(Nat(),Real()))), All("p",Prob(),All("n",Nat(),Leq(D(0),Call("weight",P,N)))), All("p",Prob(),Call("HasSum",Call("weight",P),D(1)))])), "The structure has precisely the data field weight: Nat -> Real and proof fields nonneg and normalized displayed as separate rows above; its support is unrestricted.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("DensityOperator", Disp(new Formula.Aligned([All("rho",State(),Seq(Op(Q),Colon,Ops())), All("rho",State(),Call("IsPositive",Op(Q))), All("rho",State(),Call("HasSum",Lam("n",Nat(),Re(Inner(Fock(N),At(Op(Q),Fock(N))))),D(1)))])), "The structure has precisely the data field operator and proof fields positive and trace_one displayed as separate rows above. For a positive bounded operator, finite full-basis diagonal sum characterizes trace class. No Fock-diagonality assumption is made on inputs.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("outputVector", Disp(ChannelAll(All("q",Triple(),Eqn(Call("outputVector",E,HE,P,Q,Id("q")),Smul(C(Rt(Call("weight",P,Fst(Id("q"))))),At(Call("beamSplitter",E,HE,Call("tensor",At(Call("CFC.sqrt",Op(Q)),Fock(Fst(Snd(Id("q"))))),Fock(Fst(Id("q"))))),Snd(Snd(Id("q"))))))))), "q=(n,m,l) indexes the environment number n, the square-root column m of the input, and the discarded-mode slice l. This is the square-root Kraus realization of Tr_2[U_eta(rho tensor sum_n p_n|n><n|)U_eta^dagger], including off-diagonal inputs.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("attenuatorOperator", Disp(ChannelAll(Eqn(Call("attenuatorOperator",E,HE,P,Q),Call("mixture",Triple(),Lam("q",Triple(),Call("outputVector",E,HE,P,Q,Id("q"))))))), "The displayed equation specifies the defining expression.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("attenuator", Disp(ChannelAll(Eqn(Call("operator",Call("attenuator",E,HE,P,Q)),Call("attenuatorOperator",E,HE,P,Q)))), "The state constructor has this operator field. Summability, positivity and trace one of the full triple-index ensemble are checked in Lean.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("pureDensity", Disp(All("v",HS,All("hv",Eqn(Norm(V),D(1)),Eqn(Op(Call("pureDensity",V,Id("hv"))),Rank(V))))), "The normalized vector gives its existing Mathlib rank-one projector as the operator field; positivity and trace-one proofs complete the density structure.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("pureOutputVector", Disp(All("eta",Real(),All("hEta",Icc(E),All("p",Prob(),All("v",HS,All("q",Call("Prod",Nat(),Nat()),Eqn(Call("pureOutputVector",E,HE,P,V,Id("q")),Smul(C(Rt(Call("weight",P,Fst(Id("q"))))),At(Call("beamSplitter",E,HE,Call("tensor",V,Fock(Fst(Id("q"))))),Snd(Id("q"))))))))))), "The displayed equation specifies the defining expression.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("pureAttenuatorOperator", Disp(All("eta",Real(),All("hEta",Icc(E),All("p",Prob(),All("v",HS,Eqn(Call("pureAttenuatorOperator",E,HE,P,V),Call("mixture",Call("Prod",Nat(),Nat()),Lam("q",Call("Prod",Nat(),Nat()),Call("pureOutputVector",E,HE,P,V,Id("q")))))))))), "The pure-input ensemble agrees with the full square-root attenuator. The environment expansion sums p_n times the partial trace of U_eta(v tensor |n>).", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("coherent_output_covariance", Disp(All("eta",Real(),All("hEta",Icc(E),All("p",Prob(),All("alpha",Complex(),Eqn(Call("pureAttenuatorOperator",E,HE,P,Call("displacement",A,Fock(D(0)))),Call("conjStarAlgEquiv",Call("displacement",Mul(C(Rt(E)),A)),Call("pureAttenuatorOperator",E,HE,P,Fock(D(0)))))))))), "For every countably supported phase-invariant environment, every coherent input has a displaced vacuum output. The assertion concerns the full operator, including its coherences.", DescribeRole.Theorem, AssessedProvenance.FromLiterature(Source)),
            Node("coherentDensity", Disp(All("alpha",Complex(),Eqn(Op(Call("coherentDensity",A)),Rank(Call("coherent",A))))), "The displayed equation specifies the defining expression.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("fockDensity", Disp(All("n",Nat(),Eqn(Op(Call("fockDensity",N)),Rank(Fock(N))))), "The displayed equation specifies the defining expression.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source))), []));
    private static DocumentBlock Node(string name, Formula formula, string prose, DescribeRole role, AssessedProvenance provenance) => Describe.Lean(
        DescribeId.Create("fockatt-attenuator-"+name.Replace("_", "").ToLowerInvariant()), DeclarationHandle.Create(Prefix+name), H(name),
        StatementSource.FromAuthor(formula), provenance, Blocks(Paragraph(Text(prose))), role);

    private static Formula Parenthesized(Formula x) => Seq(Open, x, Close);
    private static Formula Id(string s) => FormulaDsl.Id(s);
    private static Formula Call(string s, params Formula[] xs) => new Formula.Apply(Seq(Operatorname, Grp(Id(s.Replace(".", "").Replace("_", "")))), [.. xs]);
    private static Formula At(Formula f, params Formula[] xs) => new Formula.Apply(f, [.. xs]);
    private static Formula All(string v, Formula t, Formula b) => Seq(Forall, Sp, Id(v), Sp, Colon, Sp, t, Comma, Sp, Parenthesized(b));
    private static Formula Lam(string v, Formula t, Formula b) => Seq(Parenthesized(Seq(Id(v), Colon, t)), Mapsto, Parenthesized(b));
    private static Formula Eqn(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula Leq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula Mul(Formula a, Formula b) => new Formula.Binary(Parenthesized(a), FormulaBinaryOperator.Multiply, Parenthesized(b));
    private static Formula Norm(Formula x) => new Formula.Norm(x);
    private static Formula Fn(Formula a, Formula b) => new Formula.TypeArrow(a,b);
    private static Formula Smul(Formula a, Formula b) => Call("smul",a,b);
    private static Formula Nat() => Seq(Mathbb,Grp(Id("N")));
    private static Formula Real() => Seq(Mathbb,Grp(Id("R")));
    private static Formula Complex() => Seq(Mathbb,Grp(Id("C")));
    private static Formula HS => Call("lp", Call("Function.const", Nat(), Complex()), D(2));
    private static Formula Triple() => Call("Prod",Nat(),Call("Prod",Nat(),Nat()));
    private static Formula Ops() => Call("ContinuousLinearMap",Complex(),HS,HS);
    private static Formula Prob() => Id("ProbabilityVector");
    private static Formula State() => Id("DensityOperator");
    private static Formula A => Id("alpha");
    private static Formula N => Id("n");
    private static Formula V => Id("v");
    private static Formula E => Id("eta");
    private static Formula HE => Id("hEta");
    private static Formula P => Id("p");
    private static Formula Q => Id("rho");
    private static Formula C(Formula x) => Call("Complex.ofReal",x);
    private static Formula Rt(Formula x) => Call("sqrt",x);
    private static Formula Re(Formula x) => Call("Re",x);
    private static Formula Fst(Formula x) => Call("fst",x);
    private static Formula Snd(Formula x) => Call("snd",x);
    private static Formula Op(Formula x) => Call("operator",x);
    private static Formula Inner(Formula a, Formula b) => Call("inner",Complex(),a,b);
    private static Formula Rank(Formula x) => Call("rankOne",Complex(),x,x);
    private static Formula Icc(Formula x) => new Formula.Relation(x, FormulaRelationOperator.MemberOf, Call("Set.Icc", D(0), D(1)));
    private static Formula Fock(Formula n) => Call("lp.single", D(2), n, Call("Complex.ofReal", D(1)));
    private static Formula ChannelAll(Formula b) => All("eta",Real(),All("hEta",Icc(E),All("p",Prob(),All("rho",State(),b))));
}
